 reset(){this.touring=false;this.autoOrbit=false;this.focusTarget=null;this.controls.autoRotate=false;this.controls.target.set(0,0,0);const h=halls[this.hall],aspect=this.el.clientWidth/Math.max(this.el.clientHeight,1),factor=Math.max(1,1.12/aspect);this.camera.position.set((this.hall===1?94:88)*factor,(this.hall===1?137:113)*factor,(this.hall===1?150:126)*factor);this.camera.lookAt(0,0,0);this.controls.update();}
