 setPaused(value){this.paused=value;this.controls.autoRotate=this.autoOrbit&&!value;}
 setVisible(v){this.visible=v;if(v)this.resize();}
 resize(){const w=this.el.clientWidth,h=this.el.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();}
 topView(){this.touring=false;this.autoOrbit=false;this.controls.autoRotate=false;this.focusTarget={target:new V(0,0,0),camera:new V(0,190,.05)};}
 clear(){this.focusTarget=null;this.selected=null;if(this.selectionRig){this.world.remove(this.selectionRig);this.selectionRig.geometry.dispose();this.selectionRig.material.dispose();this.selectionRig=null;}this.filter(this.filterValue||'all');this.callbacks.onPin?.(null);}
 focus(n){this.select(n,true);}
